// Credential inventory with rotation schedules
const credentials = [
  { name: 'Google Ads OAuth2', type: 'oauth2', rotation_days: 90, last_rotated: '2025-01-15', owner: 'marketing' },
  { name: 'HubSpot API Key', type: 'apiKey', rotation_days: 90, last_rotated: '2025-02-01', owner: 'sales' },
  { name: 'Salesforce OAuth2', type: 'oauth2', rotation_days: 90, last_rotated: '2025-01-20', owner: 'sales' },
  { name: 'Meta Ads Token', type: 'oauth2', rotation_days: 60, last_rotated: '2025-02-15', owner: 'marketing' },
  { name: 'Slack Webhook', type: 'webhook', rotation_days: 365, last_rotated: '2024-06-01', owner: 'engineering' }
];

const now = new Date();
const alerts = credentials.map(cred => {
  const lastRotated = new Date(cred.last_rotated);
  const daysSinceRotation = Math.floor((now - lastRotated) / (1000 * 60 * 60 * 24));
  const daysUntilExpiry = cred.rotation_days - daysSinceRotation;
  return {
    ...cred,
    days_since_rotation: daysSinceRotation,
    days_until_expiry: daysUntilExpiry,
    status: daysUntilExpiry <= 0 ? 'EXPIRED' : daysUntilExpiry <= 7 ? 'EXPIRING_SOON' : 'OK',
    needs_alert: daysUntilExpiry <= 7
  };
});

return [{ json: { credentials: alerts, checked_at: now.toISOString() } }];

const data = $input.first().json;
const alertCredentials = data.credentials.filter(c => c.needs_alert);

const credentialBlocks = alertCredentials.map(cred => {
  const statusEmoji = cred.status === 'EXPIRED' ? ':red_circle:' : ':warning:';
  return {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `${statusEmoji} *${cred.name}*\nStatus: ${cred.status}`
      },
      {
        type: 'mrkdwn',
        text: `Type: ${cred.type}\nOwner: ${cred.owner}`
      },
      {
        type: 'mrkdwn',
        text: `Last Rotated: ${cred.last_rotated}\nDays Since: ${cred.days_since_rotation}`
      },
      {
        type: 'mrkdwn',
        text: `Rotation Policy: ${cred.rotation_days} days\nDays Until Expiry: ${cred.days_until_expiry}`
      }
    ]
  };
});

const expiredCount = alertCredentials.filter(c => c.status === 'EXPIRED').length;
const expiringSoonCount = alertCredentials.filter(c => c.status === 'EXPIRING_SOON').length;

const slackPayload = {
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: 'Credential Rotation Alert',
        emoji: true
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${expiredCount} expired* | *${expiringSoonCount} expiring soon* | Checked at: ${data.checked_at}`
      }
    },
    { type: 'divider' },
    ...credentialBlocks,
    { type: 'divider' },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: 'Please rotate the above credentials as soon as possible to avoid service disruptions.'
      }
    }
  ]
};

return [{ json: slackPayload }];
